import { render } from '@testing-library/react';
import { addMonths, format, fromUnixTime, getUnixTime } from 'date-fns';

import { subscriptionMock, upcomingSubscriptionMock } from '@proton/testing/data';

import { ExpirationTime as B2BExpirationTime } from './b2bCommonConfig';
import { ExpirationTime as B2CExpirationTime } from './b2cCommonConfig';

const currentEnd = addMonths(new Date(), 2);
const upcomingEnd = addMonths(currentEnd, 12);
const subscription = {
    ...subscriptionMock,
    PeriodEnd: getUnixTime(currentEnd),
    UpcomingSubscription: { ...upcomingSubscriptionMock, PeriodEnd: getUnixTime(upcomingEnd) },
};

it('shows the active term end date in the B2C cancellation reminder', () => {
    const { container } = render(<B2CExpirationTime subscription={subscription} cancellablePlan />);
    expect(container).toHaveTextContent(format(currentEnd, 'PP'));
    expect(container.querySelector('time')).toHaveAttribute('dateTime', format(currentEnd, 'yyyy-MM-dd'));
});

it('shows the active term end date in the B2B cancellation reminder', () => {
    const { container } = render(<B2BExpirationTime subscription={subscription} isChargeBeeUser />);
    expect(container).toHaveTextContent(format(currentEnd, 'PP'));
    expect(container.querySelector('time')).toHaveAttribute('dateTime', format(currentEnd, 'yyyy-MM-dd'));
});

